(* Setup: parameters, Lax tensors for t1, t2, t3 (exact rationals), modular reduction.  All symbols prefixed lc. *)
lcP = 4194301;                      (* prime, p < 2^22 so that all products/sums below stay exact in machine doubles *)
lcH = 1/2;
lcThStd = {2/7, -3/5, 8/11, -11/8, 5/13, -7/9};
lcThB = {1/3, -2/5, 3/4, -5/4, 2/9, -7/10};          (* task's second point; NOT generic: theta3 - theta4 = 4h *)
lcThC = {19/23, 34/29, 41/40, -19/12, -7/11, 13/17}; (* generic third point *)
lcZ = {3/2, 5/4, 2/3, 4/7};
lcA0 = 1/3;
lcMod[q_] := Mod[Numerator[q] PowerMod[Denominator[q], -1, lcP], lcP];
lcEm[i_, j_] := Normal[SparseArray[{{i, j} -> 1}, {4, 4}]];
lcRho = <|"A" -> Table[lcEm[k, l], {k, 4}, {l, 4}], "F" -> Table[-lcEm[l, k], {k, 4}, {l, 4}]|>;
lcSubs2 = Subsets[Range[4], {2}];
lcWC[k_, m_, Ir_] := Which[{k, m} == Ir, 1, {m, k} == Ir, -1, True, 0];
lcDw[X_] := Table[Sum[X[[k, Jc[[1]]]] lcWC[k, Jc[[2]], Ir] + X[[k, Jc[[2]]]] lcWC[Jc[[1]], k, Ir], {k, 4}], {Ir, lcSubs2}, {Jc, lcSubs2}];
lcDwE = Table[lcDw[lcEm[a, b]], {a, 4}, {b, 4}];           (* D(e_ab)_{IJ} on wedge^2 C^4, index [[a,b,I,J]] *)
(* Lax tensors Lax[[k,l]] = 4x4 matrix on the site (aux indices k,l) *)
lcLaxEx[1, typ_, u_, th_] := Table[(u - th) KroneckerDelta[k, l] IdentityMatrix[4] + lcH lcRho[typ][[k, l]], {k, 4}, {l, 4}];
lcLaxEx[3, "A", u_, th_] := Table[(u - th + lcH) KroneckerDelta[k, l] IdentityMatrix[4] - lcH lcEm[l, k], {k, 4}, {l, 4}];
lcLaxEx[3, "F", u_, th_] := Table[(u - th - 3 lcH) KroneckerDelta[k, l] IdentityMatrix[4] + lcH lcEm[k, l], {k, 4}, {l, 4}];
lcLaxEx[2, typ_, u_, th_] := Table[(u - th - If[typ === "F", lcH, 0]) KroneckerDelta[ii, jj] IdentityMatrix[4] + lcH Sum[lcDwE[[a, b, ii, jj]] lcRho[typ][[a, b]], {a, 4}, {b, 4}], {ii, 6}, {jj, 6}];
lcTypes[n_] := Table[If[OddQ[s], "A", "F"], {s, n}];
lcGs[1, _, _, _] := 1;
lcGs[2, "A", u_, th_] := u - th - lcH;
lcGs[2, "F", u_, th_] := u - th;
lcGs[3, "A", u_, th_] := (u - th - lcH) (u - th - 2 lcH);
lcGs[3, "F", u_, th_] := (u - th) (u - th - lcH);
lcGprod[which_, u_, ths_] := Times @@ MapThread[lcGs[which, #1, u, #2] &, {lcTypes[Length[ths]], ths}];
(* diagonal twist Lambda = diag(z): t1 uses Lambda, t3 uses det(Lambda) Lambda^{-T}, t2 uses wedge^2 Lambda *)
lcTwistDiag[1] := lcZ;
lcTwistDiag[3] := (Times @@ lcZ)/lcZ;
lcTwistDiag[2] := (Times @@ lcZ[[#]]) & /@ lcSubs2;
(* Lax as a modular (aux,site)x(aux,site) matrix of machine reals: row (k,a), column (l,b) *)
lcLaxMat[which_, typ_, u_, th_] := Module[{ex = lcLaxEx[which, typ, u, th], d = If[which == 2, 6, 4]},
  N[Mod[ArrayReshape[Transpose[Map[lcMod, ex, {4}], {1, 3, 2, 4}], {4 d, 4 d}], lcP]]];
Grid[{{"lcP", lcP}, {"h", lcH}, {"zeros of g (dropped factors) at theta_A, theta_F:", "t2(th_A+h), t2(th_F), t3(th_A+h), t3(th_A+2h), t3(th_F), t3(th_F+h)"}}, Frame -> All, Alignment -> Left]

(* One-pass action of t_a(u) on a batch of bras (columns of psi, modular integers stored as machine reals).
   psi . t_a(u): Phi[i,k] = psi delta_ik, then for each site Phi'[i,l] = sum_{k,a} Phi[i,k][..a..] Lax[k,l,a,b]; finally tr with the diagonal twist. *)
lcSite[phi_, s_, n_, d_, B_, mats_] := Module[{nl = 4^(s - 1), nr = 4^(n - s), x},
  x = Transpose[ArrayReshape[phi, {d, d, nl, 4, nr, B}], {1, 5, 2, 6, 3, 4}];   (* -> (i, nl, nr, B, k, a) *)
  x = Mod[ArrayReshape[x, {d nl nr B, 4 d}] . mats, lcP];                        (* exact: entries < 2^22, <= 24 terms *)
  x = Transpose[ArrayReshape[x, {d, nl, nr, B, d, 4}], {1, 3, 5, 6, 2, 4}];     (* -> (i, l, nl, b, nr, B) *)
  ArrayReshape[x, {d, d, nl 4 nr, B}]];
lcPass[which_, u_, ths_, psi_] := Module[{n = Length[ths], d = If[which == 2, 6, 4], B = Dimensions[psi][[2]], phi, types = lcTypes[Length[ths]], tw, out},
  phi = ConstantArray[0., {d, d, 4^n, B}];
  Do[phi[[i, i]] = psi, {i, d}];
  Do[phi = lcSite[phi, s, n, d, B, lcLaxMat[which, types[[s]], u, ths[[s]]]], {s, n}];
  tw = lcMod /@ lcTwistDiag[which];
  out = Mod[Sum[tw[[i]] phi[[i, i]], {i, d}], lcP];
  Mod[lcMod[lcGprod[which, u, ths]] out, lcP]];
(* helpers: Kronecker product of site vectors, exact -> modular *)
lcKron[vs_] := Fold[Flatten[Outer[Times, #1, #2]] &, {1}, vs];
lcModV[v_] := N[Map[lcMod, v]];
lcSiteV[a_] := {{1, 0, 0, a}, {-a, 0, 0, 1}};            (* W_a pair: A site v, F site u *)
lcPsi0[nsites_, a_: lcA0] := lcKron[Flatten[Table[lcSiteV[a], {nsites/2}], 1]];
(* sanity: all t_a(u) commute (modular, exact), 4 and 6 sites *)
lcSanity[ths_] := Module[{n = Length[ths], psi, r, res},
  SeedRandom[11]; psi = Transpose[{N[RandomInteger[{0, lcP - 1}, 4^n]]}];
  res = Table[{a, b, lcPass[a, 7/5, ths, lcPass[b, -3/7, ths, psi]] == lcPass[b, -3/7, ths, lcPass[a, 7/5, ths, psi]]}, {a, 3}, {b, a, 3}];
  Flatten[res, 1]];
Grid[Prepend[Join[Map[Prepend[#, 4] &, lcSanity[Take[lcThStd, 4]]], Map[Prepend[#, 6] &, lcSanity[lcThStd]]], {"sites", "a", "b", "[t_a(7/5), t_b(-3/7)] = 0 mod p"}], Frame -> All]

(* Word machinery.  A factor is t_a(theta_s + m h), s = 1 (A site of pair 1) or 2 (F site of pair 1), m = -4..4, a = 1,2,3.
   Identically vanishing factors (a zero of the site prefactor g) are dropped: 54 -> 48 factors. *)
lcFactors[ths_] := Select[Flatten[Table[<|"a" -> a, "s" -> s, "m" -> m, "u" -> ths[[s]] + m lcH|>, {s, 2}, {a, 3}, {m, -4, 4}], 2],
  lcGprod[#["a"], #["u"], ths] =!= 0 &];
lcFname[f_] := "t" <> ToString[f["a"]] <> "(th" <> ToString[f["s"]] <> If[f["m"] >= 0, "+", ""] <> ToString[f["m"]] <> "h)";
(* modular reduced row-echelon basis of a set of rows; rows are exact integers mod p *)
lcRR[rows_] := DeleteCases[RowReduce[Round[rows], Modulus -> lcP], {0 ..}];
lcRank[rows_] := MatrixRank[Round[rows], Modulus -> lcP];
lcIn[bas_, x_] := MatrixRank[Append[Round[bas], Round[x]], Modulus -> lcP] == Length[bas];
(* dimension of  span(bas) intersect (C^16 (x) w0):  rank-nullity for  psi -> psi (1 - w0 w0^T/(w0.w0)) on the (pair1) x (rest) reshape *)
lcLocDim[bas_, w0_] := Module[{R = Length[w0], P, proj},
  P = Mod[IdentityMatrix[R] - Outer[Times, w0, w0] PowerMod[Mod[w0 . w0, lcP], -1, lcP], lcP];
  proj = Map[Flatten[Mod[ArrayReshape[#, {16, R}] . P, lcP]] &, Round[bas]];
  Length[bas] - lcRank[proj]];
(* targets, exactly (rational), then modular.  rest = W_a^{L-1} on the other pairs *)
lcTargets[nsites_, a_: lcA0] := Module[{rest = Flatten[Table[lcSiteV[a], {nsites/2 - 1}], 1], v = lcSiteV[a][[1]], u = lcSiteV[a][[2]], T = <||>},
  Do[T[{"T1", a1}] = lcKron[Join[lcSiteV[a1], rest]], {a1, {-2/3, 0, 2/3, 5/4}}];
  Do[T[{"T2", k}] = lcKron[Join[{v (1 - k lcZ), u/(1 - k lcZ)}, rest]], {k, {1/3, -2/5, 5/3}}];
  Do[T[{"T3a", k}] = lcKron[Join[{v (1 - k/lcZ), u}, rest]], {k, {1/3, -2/5, 5/3}}];
  T[{"T3b", "vL^-1 x u(1+L)"}] = lcKron[Join[{v/lcZ, u (1 + lcZ)}, rest]];
  T[{"T3b", "vL^-1 x u(2-L)"}] = lcKron[Join[{v/lcZ, u (2 - lcZ)}, rest]];
  T];
lcTargetsMod[nsites_] := Map[lcModV, lcTargets[nsites]];
lcW0Mod[nsites_] := Round[lcModV[lcKron[Flatten[Table[lcSiteV[lcA0], {nsites/2 - 1}], 1]]]];
(* layered span: V_0 = <psi0>, V_{l+1} = V_l + sum_f V_l . t_f  (f runs over the 48 pair-1 factors, positive powers) *)
lcLayers[ths_, maxl_, chunk_: 40] := Module[{n = Length[ths], F = lcFactors[ths], psi0, bas, prev, T, w0, res = {}, cand, newDim, t0 = AbsoluteTime[]},
  psi0 = lcModV[lcPsi0[n]]; T = lcTargetsMod[n]; w0 = lcW0Mod[n];
  bas = {Round[psi0]};
  AppendTo[res, {0, 1, lcLocDim[bas, w0], Map[lcIn[bas, #] &, T], 0.}];
  Do[
   prev = bas;
   Do[
    cand = Flatten[Table[Round[Transpose[lcPass[f["a"], f["u"], ths, Transpose[blk]]]], {blk, Partition[prev, UpTo[chunk]]}], 1];
    bas = lcRR[Join[bas, cand]],               (* reduce factor by factor to keep the matrices small *)
    {f, F}];
   newDim = Length[bas] - Length[prev];
   AppendTo[res, {l, Length[bas], lcLocDim[bas, w0], Map[lcIn[bas, #] &, T], AbsoluteTime[] - t0}];
   If[newDim == 0, Break[]],
   {l, 1, maxl}];
  res];
lcLayerGrid[res_] := Grid[Prepend[Map[{#[[1]], #[[2]], #[[3]], And @@ KeyValueMap[If[#1[[1]] === "T1", #2, True] &, #[[4]]], And @@ KeyValueMap[If[#1[[1]] === "T2", #2, True] &, #[[4]]], And @@ KeyValueMap[If[#1[[1]] === "T3a", #2, True] &, #[[4]]]} &, res],
   {"layer l (<= l factors)", "rank of span", "dim localised on pair 1", "all T1 in span", "all T2 in span", "all T3a in span"}], Frame -> All, Alignment -> Left];

(* long (~hour): layers 4..6 at 3 pairs, reproduces 563 / 587 / 588 and the first appearance of T1, T2.  Run with wait_mode async. *)
lcRes3full = lcLayers[lcThStd, 6];
lcLayerGrid[lcRes3full]

## Exact identities: what is local and universal (controls T3 and the F-site step)

Exact rational check (python `Fraction`, 4 **and 6** sites, θ standard, θ′, θ″; the Wolfram cell checks the same identities mod p). With θ₁ₛ = θ₁−θ_s, ρ_s(d) = multiply the site-s components by d_i:

* ψ₀ t₁(θ₁)⁻¹ = c₁ ψ₀ρ₁(Λ⁻¹), 1/c₁ = h ∏_{F s} θ₁ₛ ∏_{A s≥2}(θ₁ₛ + h);
* ψ₀ t₃(θ₁−h) = c₃ ψ₀ρ₁(Λ⁻¹), c₃ = −(3/4) det Λ ∏_{F s}(θ₁ₛ−h)(θ₁ₛ−2h)(θ₁ₛ−4h) ∏_{A s≥3}(θ₁ₛ−h)(θ₁ₛ−2h)(θ₁ₛ−3h) (h = 1/2; −3/4 = −6h³; closed form fitted from the symbolic 4-site result, verified exactly at 5 (L,θ) points);
* ψ₀ t₁(θ₁)⁻¹ t₁(θ₂) = c₁₂ ψ₀ρ₁(Λ⁻¹)ρ₂(Λ), c₁₂ = ∏_{s≥3}[A: θ₂ₛ/(θ₁ₛ+h); F: (θ₂ₛ−h)/θ₁ₛ];
* ψ₀ t₁(θ₂) = α[ψ₀ρ₂(Λ) + (σ/α) S⊗w₀], S = Σ_i e_i⊗e_i (pair-1 singlet), w₀ = W_a^{⊗(L−1)}; at 4 sites α = hθ₁₂θ₂₃(θ₂₄−h) (times θ₂₅(θ₂₆−h) per extra pair, checked), and **σ/α = h a (z₁−z₄)/θ₁₂ is independent of L**: the F-site step always drags the singlet.

Hence T3a = ψ₀ − (κ/c₃)ψ₀t₃(θ₁−h) (two words), T3b = (α′/c₃)·ψ₀t₃(θ₁−h) + β′(c₁/(c₃c₁₂))·ψ₀t₃(θ₁−h)t₁(θ₂); each added pair multiplies c₁, c₃, c₁₂ by explicit θ-factors — *these coefficients are local/universal*. The 8 individually localised words (≤ 3 factors) are the same at L = 2 and L = 3: 1, t₃(θ₁−h), t₁(θ₂), t₁(θ₁)t₃(θ₁−h), t₃(θ₁−h)t₁(θ₂), t₁(θ₂)t₃(θ₂+3h), t₃(θ₁−h)t₁(θ₂)t₃(θ₂+3h), t₁(θ₁)t₃(θ₁−h)t₁(θ₂); their pair-1 parts span exactly 4 dimensions: ψ₀, ρ₁(Λ⁻¹)ψ₀, ρ₁(Λ⁻¹)ρ₂(Λ)ψ₀ and ρ₂(Λ)ψ₀ + (σ/α)S⊗w₀. The 10 two-word relations among words (parallel bras, e.g. t₁(θ₁−h) ∥ t₂(θ₁)t₃(θ₁−h), t₂(θ₁) ∥ t₁(θ₁−h)t₁(θ₁), t₃(θ₁) ∥ t₁(θ₁)t₂(θ₁−h), t₂(θ₁−h) ∥ t₃(θ₁−h)t₃(θ₁), t₁(θ₁−h)t₃(θ₁) ∥ t₂(θ₁−h)t₂(θ₁) and the five analogues at θ₂+h, θ₂+2h) are fusion relations and hold identically at L = 2 and L = 3.

**Expected output of the cell below** (all True): rows for 4 and 6 sites at the three θ points.

(* Exact (mod p) identities for the reachable controls and the structure of the F-site step, at 4 and 6 sites.
   rho_s(diag d) multiplies the component with site-s index i by d_i. *)
lcSiteDiag[site_, n_, dvec_] := Flatten[Fold[Outer[Times, #1, #2] &, {1}, Table[If[s == site, dvec, {1, 1, 1, 1}], {s, n}]]];
lcScaleSite[psi_, site_, n_, dvec_] := Mod[psi * (lcMod /@ lcSiteDiag[site, n, dvec]), lcP];     (* psi: flat modular vector *)
lcC1[ths_] := 1/(lcH Product[If[OddQ[s], ths[[1]] - ths[[s]] + lcH, ths[[1]] - ths[[s]]], {s, 2, Length[ths]}]);
lcC3[ths_] := -(3/4) (Times @@ lcZ) Product[With[{d = ths[[1]] - ths[[s]]}, If[OddQ[s], (d - lcH) (d - 2 lcH) (d - 3 lcH), (d - lcH) (d - 2 lcH) (d - 4 lcH)]], {s, 2, Length[ths]}];
lcC12[ths_] := Product[If[OddQ[s], (ths[[2]] - ths[[s]])/(ths[[1]] - ths[[s]] + lcH), (ths[[2]] - ths[[s]] - lcH)/(ths[[1]] - ths[[s]])], {s, 3, Length[ths]}];
lcCtrl[ths_] := Module[{n = Length[ths], psi0, flat, col, p1, r1, r2, r3, x, w0, alpha, sigma, S, vu, fit},
  psi0 = Round[lcModV[lcPsi0[n]]]; col = Transpose[{psi0}]; w0 = lcW0Mod[n];
  p1 = lcScaleSite[psi0, 1, n, 1/lcZ];                                   (* psi0 rho_1(Lambda^-1) *)
  (* (1) calibration  psi0 = c1 (psi0 rho_1(L^-1)) t1(th1) *)
  r1 = Flatten[lcPass[1, ths[[1]], ths, Transpose[{Mod[lcMod[lcC1[ths]] p1, lcP]}]]] == psi0;
  (* (2) (psi0 t1(th1)^-1) t1(th2) = c12 psi0 rho_1(L^-1) rho_2(L) *)
  r2 = Flatten[lcPass[1, ths[[2]], ths, Transpose[{Mod[lcMod[lcC1[ths]] p1, lcP]}]]] == Mod[lcMod[lcC12[ths]] lcScaleSite[p1, 2, n, lcZ], lcP];
  (* (3) psi0 t3(th1-h) = c3 psi0 rho_1(L^-1) *)
  r3 = Flatten[lcPass[3, ths[[1]] - lcH, ths, col]] == Mod[lcMod[lcC3[ths]] p1, lcP];
  (* (4) psi0 t1(th2) = alpha psi0 rho_2(L) + sigma S (x) w0  (S = sum_i e_i (x) e_i on pair 1) *)
  x = Mod[Mod[ArrayReshape[Flatten[lcPass[1, ths[[2]], ths, col]], {16, Length[w0]}] . w0, lcP] PowerMod[Mod[w0 . w0, lcP], -1, lcP], lcP];
  alpha = Mod[x[[4]] PowerMod[lcMod[lcZ[[4]]], -1, lcP], lcP];          (* (A=1,F=4) entry of v (x) u Lam is z4 *)
  sigma = x[[6]];                                                          (* (A=2,F=2) entry: pure singlet *)
  vu = Flatten[KroneckerProduct[lcModV[lcSiteV[lcA0][[1]]], lcModV[lcSiteV[lcA0][[2]] lcZ]]];
  S = Flatten[IdentityMatrix[4]];
  fit = Mod[alpha vu + sigma S, lcP] == x;
  {n, r1, r2, r3, fit}];
Grid[Prepend[Join[Table[lcCtrl[Take[ths, 4]], {ths, {lcThStd, lcThB, lcThC}}], Table[lcCtrl[ths], {ths, {lcThStd, lcThB, lcThC}}]],
  {"sites", "psi0 = c1 psi0 rho1(L^-1) t1(th1)", "t1(th1)^-1 t1(th2) -> c12 rho1(L^-1)rho2(L)", "t3(th1-h) -> c3 rho1(L^-1)", "t1(th2) psi0 = alpha rho2(L) psi0 + sigma S (x) w0"}], Frame -> All, Alignment -> Left]

(* T1 and T2 lie in  span{psi0, psi0 t3(th1-h), psi0 t3(th1-h) t1(th2), psi0 t1(th2)}  (+)  C (S (x) W_a^{L-1}),  S = sum_i e_i (x) e_i on pair 1.
   The four words are the individually localised 'SoV' words; the whole obstruction is the isolated pair singlet. *)
lcFourPlusS[ths_] := Module[{n = Length[ths], psi0, col, w3, w31, w1b, S, T, B4, B5, t12},
  psi0 = Round[lcModV[lcPsi0[n]]]; col = Transpose[{psi0}];
  w3 = Round[Flatten[lcPass[3, ths[[1]] - lcH, ths, col]]];
  w31 = Round[Flatten[lcPass[1, ths[[2]], ths, Transpose[{w3}]]]];
  w1b = Round[Flatten[lcPass[1, ths[[2]], ths, col]]];
  S = Round[lcModV[lcKron[Join[{Flatten[IdentityMatrix[4]]}, Flatten[Table[lcSiteV[lcA0], {n/2 - 1}], 1]]]]];
  T = Select[lcTargetsMod[n], True &]; t12 = KeySelect[T, MemberQ[{"T1", "T2"}, #[[1]]] &];
  B4 = {psi0, w3, w31, w1b}; B5 = Append[B4, S];
  {n, lcRank[B4], lcRank[B5], lcIn[B4, S], And @@ Map[lcIn[B4, #] &, Values[t12]], And @@ Map[lcIn[B5, #] &, Values[t12]]}];
Grid[Prepend[Flatten[Table[Prepend[Rest[lcFourPlusS[Take[ths, n]]], n], {ths, {lcThStd, lcThB, lcThC}}, {n, {4, 6}}], 1],
  {"sites", "rank 4 words", "rank 4 words + S(x)w0", "S(x)w0 in span(4 words)", "all T1,T2 in span(4 words)", "all T1,T2 in span(4 words + S(x)w0)"}], Frame -> All, Alignment -> Left]

(* Full cyclic space of psi0 under the commutative algebra of ALL t_a(u) (any shifts, any powers, inverses included, since the
   restriction of an invertible operator to a finite-dimensional invariant subspace has an inverse that is a polynomial in it):
   Krylov space of one generic element M = t1(u1) + c2 t2(u2) + c3 t3(u3) of the algebra, modular exact. *)
lcKrylov[ths_, nvec_, seed_: 1] := Module[{n = Length[ths], psi0, u1, u2, u3, c2, c3, x, vecs},
  SeedRandom[seed];
  {u1, u2, u3} = Table[RandomInteger[{-97, 97}]/RandomInteger[{11, 53}], {3}];
  {c2, c3} = RandomInteger[{2, lcP - 2}, 2];
  psi0 = Round[lcModV[lcPsi0[n]]]; x = Transpose[{psi0}];
  vecs = Table[With[{cur = x}, x = Mod[lcPass[1, u1, ths, cur] + Mod[c2 lcPass[2, u2, ths, cur], lcP] + Mod[c3 lcPass[3, u3, ths, cur], lcP], lcP]; Flatten[cur]], {nvec}];
  lcRR[vecs]];
lcKrylovReport[ths_, nvec_, seed_: 1] := Module[{n = Length[ths], bas = lcKrylov[ths, nvec, seed], T = lcTargetsMod[Length[ths]], w0 = lcW0Mod[Length[ths]]},
  {n, nvec, Length[bas], lcLocDim[bas, w0], And @@ Map[lcIn[bas, #] &, Values[KeySelect[T, #[[1]] === "T1" &]]],
   And @@ Map[lcIn[bas, #] &, Values[KeySelect[T, #[[1]] === "T2" &]]], And @@ Map[lcIn[bas, #] &, Values[KeySelect[T, #[[1]] === "T3a" &]]]}];
lcKry2 = lcKrylovReport[Take[lcThStd, 4], 70];
lcKry3 = lcKrylovReport[lcThStd, 650];
Grid[{{"sites", "# Krylov vectors generated", "cyclic dimension (rank)", "dim localised on pair 1", "all T1", "all T2", "all T3a"}, lcKry2, lcKry3}, Frame -> All, Alignment -> Left]
